def match(orders):
    trades = []

    # Book structure: dict of side -> list of (arrival_time, id, price, remaining_qty)
    book = {'buy': [], 'sell': []}

    # Track order state for cancellation
    order_state = {}  # id -> {'filled': qty, 'resting': True/False, 'arrival_time': int}

    arrival_time = 0

    for order in orders:
        cmd = order[0]

        if cmd == 'cancel':
            order_id = order[1]
            if order_id in order_state and order_state[order_id]['resting']:
                # Remove from book
                side = order_state[order_id]['side']
                book[side] = [(t, oid, p, q) for t, oid, p, q in book[side] if oid != order_id]
                order_state[order_id]['resting'] = False

        elif cmd == 'limit':
            order_id = order[1]
            side = order[2]
            price = order[3]
            qty = order[4]

            order_state[order_id] = {'filled': 0, 'resting': True, 'arrival_time': arrival_time, 'side': side}

